cd /bench/repo; python3 - <<'EOF'
import os,re,subprocess,collections
decls=collections.defaultdict(set)  # name -> set of dirs
for root,d,files in os.walk('internal'):
    for fn in files:
        if not fn.endswith('.go'): continue
        p=os.path.join(root,fn)
        src=open(p).read()
        for m in re.finditer(r'^func (?:\([^)]*\) )?([A-Za-z_]\w*)\s*\(', src, re.M):
            n=m.group(1)
            if n.startswith(('Test','Benchmark','Fuzz','Example')): continue
            if fn.endswith('_test.go'): continue
            decls[n].add(root)

# gather all go files
allfiles=[]
for root,d,files in os.walk('.'):
    if 'proto/gen' in root or '/node_modules' in root or root.startswith('./web'): continue
    for fn in files:
        if fn.endswith('.go'): allfiles.append(os.path.join(root,fn))
cache={f:open(f).read() for f in allfiles}

res=[]
for n,dirs in decls.items():
    tot=0; nontest=0; sites=[]
    pat=re.compile(r'(?<![\w.])'+re.escape(n)+r'\s*\(')
    patq=re.compile(r'\.'+re.escape(n)+r'\s*\(')
    for f,src in cache.items():
        d=os.path.dirname(f)
        for i,line in enumerate(src.split('\n'),1):
            if line.lstrip().startswith('func '): continue
            hit=False
            if d in dirs and pat.search(line): hit=True
            if patq.search(line) and (d in dirs or True):
                # qualified: could be pkg.Name or recv.Name
                hit=True
            if hit:
                tot+=1
                if not f.endswith('_test.go'): nontest+=1
                sites.append(f)
    res.append((tot,nontest,n))
res.sort(reverse=True)
for t,nt,n in res[:20]:
    print(t,nt,n)
EOF

